import React, { useState } from 'react';
import { 
  EnvelopeIcon, 
  PhoneIcon, 
  MapPinIcon, 
  ClockIcon,
  PaperAirplaneIcon,
  BuildingOfficeIcon,
  ChatBubbleLeftRightIcon,
  UserIcon,
  CheckCircleIcon
} from '@heroicons/react/24/outline';
import { 
  Facebook, 
  Twitter, 
  Instagram, 
  Linkedin,
  Mail,
  MessageSquare,
  Map,
  Globe
} from 'lucide-react';

const ContactPage = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    subject: '',
    message: '',
    consent: false
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [formErrors, setFormErrors] = useState({});

  const validateForm = () => {
    const errors = {};

    if (!formData.name.trim()) errors.name = "Le nom est requis";
    if (!formData.email.trim()) {
      errors.email = "L'email est requis";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      errors.email = "Format d'email invalide";
    }
    if (!formData.subject) errors.subject = "Veuillez sélectionner un sujet";
    if (!formData.message.trim()) errors.message = "Le message est requis";
    if (!formData.consent) errors.consent = "Vous devez accepter la politique de confidentialité";

    return errors;
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));

    // Effacer l'erreur pour ce champ
    if (formErrors[name]) {
      setFormErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const errors = validateForm();
    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      return;
    }

    setIsSubmitting(true);

    try {
      // Simulation d'envoi de formulaire - À remplacer par votre API
      await new Promise(resolve => setTimeout(resolve, 2000));

      console.log('Form data submitted:', formData);
      setSubmitSuccess(true);
      setFormData({
        name: '',
        email: '',
        phone: '',
        subject: '',
        message: '',
        consent: false
      });
      setFormErrors({});

      // Réinitialiser le message de succès après 5 secondes
      setTimeout(() => setSubmitSuccess(false), 5000);
    } catch (error) {
      console.error('Submission error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const contactInfo = [
    {
      icon: <PhoneIcon className="h-8 w-8" />,
      title: "Téléphone",
      details: ["+33 1 23 45 67 89", "+33 1 98 76 54 32"],
      description: "Lundi - Vendredi, 9h-18h",
      color: "bg-gradient-to-r from-blue-500 to-blue-600",
      action: "Appeler maintenant",
      href: "tel:+33123456789"
    },
    {
      icon: <EnvelopeIcon className="h-8 w-8" />,
      title: "Email",
      details: ["contact@entreprise.com", "support@entreprise.com"],
      description: "Réponse sous 24h",
      color: "bg-gradient-to-r from-green-500 to-emerald-600",
      action: "Envoyer un email",
      href: "mailto:contact@entreprise.com"
    },
    {
      icon: <MapPinIcon className="h-8 w-8" />,
      title: "Adresse",
      details: ["123 Avenue des Champs-Élysées", "75008 Paris, France"],
      description: "Bureau ouvert au public",
      color: "bg-gradient-to-r from-purple-500 to-purple-600",
      action: "Voir sur la carte",
      href: "#map"
    },
    {
      icon: <ClockIcon className="h-8 w-8" />,
      title: "Horaires",
      details: ["Lun - Ven: 9h00 - 18h00", "Sam: 10h00 - 14h00"],
      description: "Fermé les dimanches et jours fériés",
      color: "bg-gradient-to-r from-orange-500 to-orange-600",
      action: "Prendre RDV",
      href: "#"
    }
  ];

  const faqs = [
    {
      question: "Quel est le délai de réponse moyen ?",
      answer: "Nous répondons à toutes les demandes dans un délai de 24 à 48 heures ouvrées."
    },
    {
      question: "Comment obtenir un devis personnalisé ?",
      answer: "Remplissez notre formulaire de contact en détaillant vos besoins ou appelez-nous directement pour discuter de votre projet."
    },
    {
      question: "Proposez-vous des consultations gratuites ?",
      answer: "Oui, nous offrons une première consultation gratuite de 30 minutes pour évaluer vos besoins."
    },
    {
      question: "Quelles sont vos méthodes de paiement ?",
      answer: "Nous acceptons les cartes bancaires, virements et PayPal pour tous nos services."
    }
  ];

  const socialLinks = [
    { 
      icon: <Facebook className="h-6 w-6" />, 
      name: "Facebook", 
      url: "#", 
      color: "bg-gradient-to-r from-blue-600 to-blue-700",
      hover: "hover:from-blue-700 hover:to-blue-800"
    },
    { 
      icon: <Twitter className="h-6 w-6" />, 
      name: "Twitter", 
      url: "#", 
      color: "bg-gradient-to-r from-sky-500 to-sky-600",
      hover: "hover:from-sky-600 hover:to-sky-700"
    },
    { 
      icon: <Instagram className="h-6 w-6" />, 
      name: "Instagram", 
      url: "#", 
      color: "bg-gradient-to-r from-pink-600 to-rose-600",
      hover: "hover:from-pink-700 hover:to-rose-700"
    },
    { 
      icon: <Linkedin className="h-6 w-6" />, 
      name: "LinkedIn", 
      url: "#", 
      color: "bg-gradient-to-r from-blue-700 to-blue-800",
      hover: "hover:from-blue-800 hover:to-blue-900"
    }
  ];

  const subjects = [
    { value: "", label: "Sélectionnez un sujet" },
    { value: "support", label: "Support technique" },
    { value: "sales", label: "Demande commerciale" },
    { value: "partnership", label: "Partenariat" },
    { value: "career", label: "Carrières" },
    { value: "other", label: "Autre" }
  ];

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white">
      {/* Hero Section avec animation */}
      <div className="relative overflow-hidden bg-gradient-to-r from-blue-600 via-blue-700 to-indigo-800 text-white py-20 md:py-24">
        <div className="absolute inset-0">
          <div className="absolute inset-0 bg-black opacity-20"></div>
          <div className="absolute top-0 left-0 w-full h-full">
            <div className="absolute top-10 left-10 w-72 h-72 bg-blue-400 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob"></div>
            <div className="absolute top-20 right-10 w-72 h-72 bg-purple-400 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-2000"></div>
            <div className="absolute -bottom-8 left-20 w-72 h-72 bg-pink-400 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-blob animation-delay-4000"></div>
          </div>
        </div>

        <div className="container mx-auto px-4 relative z-10">
          <div className="max-w-3xl mx-auto text-center">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-white/10 backdrop-blur-sm rounded-2xl mb-6">
              <MessageSquare className="h-10 w-10" />
            </div>
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6 leading-tight">
              Contactez-<span className="text-blue-200">nous</span>
            </h1>
            <p className="text-xl md:text-2xl mb-10 opacity-90 leading-relaxed">
              Notre équipe est à votre écoute pour répondre à toutes vos questions et vous accompagner dans vos projets
            </p>
            <div className="flex flex-wrap justify-center gap-4">
              <div className="flex items-center bg-white/10 backdrop-blur-sm rounded-xl px-5 py-3 border border-white/20">
                <ClockIcon className="h-5 w-5 mr-2" />
                <span>Réponse sous 24h</span>
              </div>
              <div className="flex items-center bg-white/10 backdrop-blur-sm rounded-xl px-5 py-3 border border-white/20">
                <ChatBubbleLeftRightIcon className="h-5 w-5 mr-2" />
                <span>Support 5j/7</span>
              </div>
              <div className="flex items-center bg-white/10 backdrop-blur-sm rounded-xl px-5 py-3 border border-white/20">
                <CheckCircleIcon className="h-5 w-5 mr-2" />
                <span>100% satisfaction</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="container mx-auto px-4 py-12 md:py-16">
        <div className="grid lg:grid-cols-2 gap-12">
          {/* Contact Information */}
          <div>
            <h2 className="text-3xl md:text-4xl font-bold text-gray-800 mb-10">
              <BuildingOfficeIcon className="h-10 w-10 inline-block mr-3 text-blue-600" />
              Notre équipe vous attend
            </h2>

            <div className="grid md:grid-cols-2 gap-6 mb-12">
              {contactInfo.map((info, index) => (
                <div 
                  key={index} 
                  className="group bg-white rounded-2xl shadow-lg p-6 hover:shadow-2xl transition-all duration-300 border border-gray-100"
                >
                  <div className={`${info.color} w-14 h-14 rounded-xl flex items-center justify-center mb-5 group-hover:scale-110 transition-transform duration-300`}>
                    <div className="text-white">
                      {info.icon}
                    </div>
                  </div>
                  <h3 className="font-bold text-gray-800 text-xl mb-3">{info.title}</h3>
                  {info.details.map((detail, idx) => (
                    <p key={idx} className="text-gray-600 mb-2">{detail}</p>
                  ))}
                  <p className="text-sm text-gray-500 mb-4">{info.description}</p>
                  <a 
                    href={info.href}
                    className="inline-flex items-center text-blue-600 font-medium hover:text-blue-700 transition-colors"
                  >
                    <span>{info.action}</span>
                    <svg className="w-4 h-4 ml-2 transform group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                  </a>
                </div>
              ))}
            </div>

            {/* Social Media */}
            <div className="bg-gradient-to-r from-gray-50 to-white rounded-2xl shadow-xl p-8 mb-12 border border-gray-100">
              <h3 className="text-2xl font-bold text-gray-800 mb-6 flex items-center">
                <Globe className="h-6 w-6 mr-2 text-blue-600" />
                Suivez-nous sur les réseaux
              </h3>
              <div className="flex flex-wrap gap-4">
                {socialLinks.map((social, index) => (
                  <a
                    key={index}
                    href={social.url}
                    className={`${social.color} ${social.hover} text-white p-4 rounded-xl hover:shadow-lg transition-all duration-300 flex items-center space-x-3 transform hover:-translate-y-1`}
                  >
                    {social.icon}
                    <span className="font-semibold">{social.name}</span>
                  </a>
                ))}
              </div>
            </div>

            {/* FAQ Section */}
            <div className="mt-12">
              <h3 className="text-2xl font-bold text-gray-800 mb-8 flex items-center">
                <ChatBubbleLeftRightIcon className="h-6 w-6 mr-2 text-blue-600" />
                Questions fréquentes
              </h3>
              <div className="space-y-4">
                {faqs.map((faq, index) => (
                  <div 
                    key={index} 
                    className="group bg-white rounded-xl shadow-md p-6 hover:shadow-xl transition-all duration-300 border-l-4 border-blue-500 hover:border-blue-600 cursor-pointer"
                  >
                    <h4 className="font-bold text-gray-800 mb-3 text-lg group-hover:text-blue-600 transition-colors">
                      {faq.question}
                    </h4>
                    <p className="text-gray-600 leading-relaxed">{faq.answer}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Contact Form */}
          <div className="bg-white rounded-3xl shadow-2xl p-8 md:p-10 sticky top-8 border border-gray-100">
            <div className="flex items-center mb-2">
              <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-blue-600 rounded-xl flex items-center justify-center mr-4">
                <Mail className="h-6 w-6 text-white" />
              </div>
              <div>
                <h2 className="text-3xl font-bold text-gray-800">
                  Envoyez-nous un message
                </h2>
                <p className="text-gray-600">
                  Remplissez le formulaire ci-dessous
                </p>
              </div>
            </div>

            {submitSuccess && (
              <div className="bg-gradient-to-r from-green-50 to-emerald-50 border border-green-200 rounded-xl p-5 mb-8 animate-fade-in">
                <div className="flex items-center">
                  <div className="bg-green-100 p-3 rounded-full mr-4">
                    <CheckCircleIcon className="h-6 w-6 text-green-600" />
                  </div>
                  <div>
                    <p className="font-bold text-green-800 text-lg">Message envoyé avec succès !</p>
                    <p className="text-green-700">Nous vous répondrons dans les plus brefs délais.</p>
                  </div>
                </div>
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-8">
              <div className="grid md:grid-cols-2 gap-6">
                <div>
                  <label htmlFor="name" className="block text-gray-700 font-semibold mb-3 flex items-center">
                    <UserIcon className="h-4 w-4 mr-2 text-blue-600" />
                    Nom complet *
                  </label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    required
                    className={`w-full px-4 py-3.5 border rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition ${
                      formErrors.name ? 'border-red-500' : 'border-gray-300 focus:border-transparent'
                    }`}
                    placeholder="John Doe"
                  />
                  {formErrors.name && (
                    <p className="text-red-500 text-sm mt-2">{formErrors.name}</p>
                  )}
                </div>

                <div>
                  <label htmlFor="email" className="block text-gray-700 font-semibold mb-3 flex items-center">
                    <EnvelopeIcon className="h-4 w-4 mr-2 text-blue-600" />
                    Email *
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    required
                    className={`w-full px-4 py-3.5 border rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition ${
                      formErrors.email ? 'border-red-500' : 'border-gray-300 focus:border-transparent'
                    }`}
                    placeholder="john@exemple.com"
                  />
                  {formErrors.email && (
                    <p className="text-red-500 text-sm mt-2">{formErrors.email}</p>
                  )}
                </div>
              </div>

              <div className="grid md:grid-cols-2 gap-6">
                <div>
                  <label htmlFor="phone" className="block text-gray-700 font-semibold mb-3 flex items-center">
                    <PhoneIcon className="h-4 w-4 mr-2 text-blue-600" />
                    Téléphone
                  </label>
                  <input
                    type="tel"
                    id="phone"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full px-4 py-3.5 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition"
                    placeholder="+33 1 23 45 67 89"
                  />
                </div>

                <div>
                  <label htmlFor="subject" className="block text-gray-700 font-semibold mb-3">
                    Sujet *
                  </label>
                  <select
                    id="subject"
                    name="subject"
                    value={formData.subject}
                    onChange={handleInputChange}
                    required
                    className={`w-full px-4 py-3.5 border rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition ${
                      formErrors.subject ? 'border-red-500' : 'border-gray-300 focus:border-transparent'
                    }`}
                  >
                    {subjects.map((option, index) => (
                      <option key={index} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                  {formErrors.subject && (
                    <p className="text-red-500 text-sm mt-2">{formErrors.subject}</p>
                  )}
                </div>
              </div>

              <div>
                <label htmlFor="message" className="block text-gray-700 font-semibold mb-3">
                  Message *
                </label>
                <textarea
                  id="message"
                  name="message"
                  value={formData.message}
                  onChange={handleInputChange}
                  required
                  rows="6"
                  className={`w-full px-4 py-3.5 border rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition resize-none ${
                    formErrors.message ? 'border-red-500' : 'border-gray-300 focus:border-transparent'
                  }`}
                  placeholder="Décrivez votre demande en détail..."
                />
                {formErrors.message && (
                  <p className="text-red-500 text-sm mt-2">{formErrors.message}</p>
                )}
              </div>

              <div className="bg-blue-50 rounded-xl p-5">
                <div className="flex items-start">
                  <input
                    type="checkbox"
                    id="consent"
                    name="consent"
                    checked={formData.consent}
                    onChange={handleInputChange}
                    required
                    className="h-5 w-5 text-blue-600 rounded focus:ring-blue-500 mt-1"
                  />
                  <label htmlFor="consent" className="ml-3 text-gray-700">
                    <span className="font-medium">J'accepte la{' '}
                      <a href="#" className="text-blue-600 hover:underline font-semibold">
                        politique de confidentialité
                      </a>{' '}
                      *
                    </span>
                    {formErrors.consent && (
                      <p className="text-red-500 text-sm mt-1">{formErrors.consent}</p>
                    )}
                  </label>
                </div>
              </div>

              <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-semibold py-4 px-6 rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-3 shadow-lg hover:shadow-xl transform hover:-translate-y-0.5"
              >
                {isSubmitting ? (
                  <>
                    <div className="h-5 w-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-lg">Envoi en cours...</span>
                  </>
                ) : (
                  <>
                    <PaperAirplaneIcon className="h-6 w-6" />
                    <span className="text-lg">Envoyer le message</span>
                  </>
                )}
              </button>

              <p className="text-sm text-gray-500 text-center">
                * Champs obligatoires
              </p>
            </form>
          </div>
        </div>
      </div>

      {/* Map Section */}
      <div id="map" className="container mx-auto px-4 py-12 md:py-16">
        <div className="bg-gradient-to-br from-gray-50 to-white rounded-3xl shadow-2xl p-8 md:p-10 border border-gray-100">
          <div className="text-center mb-10">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-800 mb-4">
              Notre localisation
            </h2>
            <p className="text-gray-600 text-lg max-w-2xl mx-auto">
              Venez nous rencontrer dans notre bureau situé au cœur de Paris
            </p>
          </div>

          <div className="grid md:grid-cols-3 gap-8 mb-8">
            <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-2xl p-6 border border-blue-200">
              <h3 className="font-bold text-gray-800 text-xl mb-3">Accès</h3>
              <ul className="space-y-2 text-gray-600">
                <li className="flex items-center">
                  <MapPinIcon className="h-4 w-4 mr-2 text-blue-600" />
                  Métro: Charles de Gaulle - Étoile
                </li>
                <li className="flex items-center">
                  <MapPinIcon className="h-4 w-4 mr-2 text-blue-600" />
                  Bus: 73, 93
                </li>
                <li className="flex items-center">
                  <MapPinIcon className="h-4 w-4 mr-2 text-blue-600" />
                  Parking: Q-Park Étoile
                </li>
              </ul>
            </div>

            <div className="bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-2xl p-6 border border-indigo-200">
              <h3 className="font-bold text-gray-800 text-xl mb-3">Horaires de visite</h3>
              <ul className="space-y-2 text-gray-600">
                <li className="flex justify-between">
                  <span>Lundi - Vendredi</span>
                  <span className="font-medium">9h00 - 18h00</span>
                </li>
                <li className="flex justify-between">
                  <span>Samedi</span>
                  <span className="font-medium">10h00 - 14h00</span>
                </li>
                <li className="flex justify-between">
                  <span>Dimanche</span>
                  <span className="font-medium text-red-500">Fermé</span>
                </li>
              </ul>
            </div>

            <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-2xl p-6 border border-purple-200">
              <h3 className="font-bold text-gray-800 text-xl mb-3">Visite sur rendez-vous</h3>
              <p className="text-gray-600 mb-4">
                Pour une visite en dehors des horaires d'ouverture, prenez rendez-vous à l'avance.
              </p>
              <button className="w-full bg-gradient-to-r from-purple-600 to-purple-700 text-white font-semibold py-3 px-4 rounded-lg hover:from-purple-700 hover:to-purple-800 transition">
                Prendre rendez-vous
              </button>
            </div>
          </div>

          <div className="bg-gradient-to-r from-blue-100 to-indigo-100 rounded-2xl h-80 md:h-96 flex items-center justify-center overflow-hidden border border-gray-200">
            <div className="text-center p-8">
              <Map className="h-16 w-16 text-blue-600 mx-auto mb-4" />
              <p className="text-gray-700 font-bold text-xl mb-2">123 Avenue des Champs-Élysées</p>
              <p className="text-gray-600 mb-6">75008 Paris, France</p>
              <button className="bg-white text-blue-600 font-semibold py-3 px-8 rounded-lg hover:bg-blue-50 transition-all duration-300 shadow-lg hover:shadow-xl flex items-center mx-auto">
                <MapPinIcon className="h-5 w-5 mr-2" />
                Voir sur Google Maps
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Style pour les animations */}
      <style jsx>{`
        @keyframes blob {
          0% { transform: translate(0px, 0px) scale(1); }
          33% { transform: translate(30px, -50px) scale(1.1); }
          66% { transform: translate(-20px, 20px) scale(0.9); }
          100% { transform: translate(0px, 0px) scale(1); }
        }
        .animate-blob {
          animation: blob 7s infinite;
        }
        .animation-delay-2000 {
          animation-delay: 2s;
        }
        .animation-delay-4000 {
          animation-delay: 4s;
        }
        .animate-fade-in {
          animation: fadeIn 0.5s ease-out;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default ContactPage;
